        "dua_jannah_nar" to DuaText("جنت، نارٕ نش پناہ گزین پوچھن", "اے اللہ، بہٕ چھس تۄہہ جنت خٲطرٕ عرض کران تہٕ بہٕ چھس تۄہہ نار نش پناہ یژھان۔", "تاشاہد پتہٕ یا کنہ تہ وقتہٕ۔", "پیغمبر صلی اللہ علیہ وسلم ین ووٚن: سٕنٛدیٚن دواہن ہنٛدۍ تہ چھ اتھ انٛدۍ پٔکہٕ چکر۔"),
        "dua_khayri_kullih" to DuaText("تمام اصل، اب تہٕ بعد میں", "اے اللہ، بہٕ چھس تۄہہ تمام بھلائی طلب کران-فوری تہٕ تاخیر، یس بہٕ چھس جانان تہٕ یس نہٕ جانان-تہٕ بہٕ چھس تۄہہ منٛز تمام برائتہٕ نش پناہ مانگان-فوری تہٕ تاخیر، یس بہٕ چھس جانان تہٕ یس نہٕ جانان۔ اے اللہ، بہٕ چھس تۄہہ جنت خٲطرٕ درخواست کران تہٕ یم الفاظ تہٕ اعمال چھ مےٚ اتھ قریب نوان، تہٕ بہٕ چھس تۄہہ منٛز آگ نش پناہ مانگان تہٕ یم الفاظ تہٕ اعمال چھ مےٚ اتھ قریب نوان۔", "پیغمبر صلی اللہ علیہ وسلم ین سکھٲو یہ جامع دعا عائشہ (ر) (دعا ہک حصہٕ)۔", "اکھ دوا یس پرٛؠتھ اچھٲئی جمع چھ کران۔"),
        "dua_ihdini_saddidni" to DuaText("مےٚ کر رہنما تہٕ مےٚ تھٲیو صاف۔", "اے اللہ، مےٚ کر ہدایت تہٕ مےٚ تھٲیو صحیح وتھ۔", "پیغمبر اسلام صلی اللہ علیہ وسلم ین سکھاو یہ علی (ر) یس۔", "سڑکہ پیٹھ رہنمائی کس طورس پیٹھ سونچو، تہٕ صدادس تیر کہ سیدھی پن کس طورس پیٹھ۔"),
        "dua_hubbaka" to DuaText("اللہ ہیچ محبت منٛذ", "اے اللہ، بہٕ چھس تۄہہ محبت، تمن لوکن ہنٛز محبت، تہٕ تم اعمال یم مےٚ تہنٛد پیارس منٛز چھ نوان۔ اے اللہ، پنن محبت مےٚ میانہ، میٲنس خاندانس تہٕ ٹھنڈے آب کھوتہٕ زیادٕ پیٛو۔", "داؤد (ع) سند دوع یس پیغمبر اسلام صلی اللہ علیہ وسلم سند حوالہٕ چھ۔", "اللہ پاکس چھ محبتک ساروی کھوتہٕ بڑ وسیلہ۔"),
        "dua_filal_khayrat" to DuaText("اچھٲئی تہٕ برٲئی چھ چھوڑنننننن", "اے اللہ، بہٕ چھس تۄہہ پوچھنان ز بہٕ ہؠکہٕ اصل کٲم کٔرتھ، شرۍ اعمال ترٛٲوتھ تہٕ غریبن سۭتۍ محبت کٔرتھ، تہٕ یہ ز تہۍ چھو مےٚ معاف تہٕ مےٚ کر رحم۔ تہٕ ییٚلہ تہۍ لوکن خٲطرٕ مقدمہٕ ہنٛد ارادٕ چھو کران، مےٚ کٔرو آزماونہٕ بغٲر۔ بہٕ چھس تۄہہ محبت، تم لوکن ہنٛز محبت تہٕ تمن عملن ہنٛز محبت یژھان یس مےٚ تہنٛدس محبتس قریب چھ نوان۔", "اللہ چھ یہ دعا پیغمبر اسلام صلی اللہ علیہ وسلم سٕند خوابس منز سکھاوان۔", "پیغمبر اسلام صلی اللہ علیہ وسلم ۄن ز یہ چھ سچ، تو٘ہہ ہیٚچھنو یہ تہٕ ہیچھناو یہ۔"),
        "dua_bi_ilmikal_ghayb" to DuaText("مےٚ زٲنۍ ییلہٕ زندگی اصل آسہ۔", "اے اللہ، پننس پوشیدہ علمس تہٕ تخلیقس پیٹھ پننہٕ طاقتس سۭتۍ-مےٚ تھیو زندہ یوٚتام تام ز تم جان چھ زندگی میانہ خاطرٕ بہتر، تہٕ مےٚ تھیو ییلہٕ تم جان ز موت چھ میانہ خاطرٕ بہتر۔ اے اللہ، بہٕ چھس تۄہہ نجی تہٕ عوٲمی طور پأنٹھ خوفٕ خاطرٕ، اطمینان تہٕ غصے منٛز سچائی ہنٛد لفظ خاطرٕ، تہٕ غربت تہٕ دولتس منٛز اعتدال خاطرٕ پوچھان۔", "عمار ابن یاسر (ر) (افتتاحی حصہ)۔", "پیغمبر اسلام صلی اللہ علیہ وسلم چھ یہ دعا دعایہ منٛز پیش کران۔"),
        "dua_ism_azam_mannan" to DuaText("اسلام اعظم: المنان", "اے اللہ، بہٕ چھس تۄہہ پوچھنان، ساری تعریف چھ تۄہہہ سۭتۍ۔ تہنٛدس علاوٕ چھ نہٕ کانٛہہ تہ دیوتا، یس فضلہٕ چھ دوان، یس آسمان تہٕ زمینک خالق چھ۔ اے عظمت تہٕ عزتک مالک، اے ابدی، اے سرپرست!", "پیغمبر صلی اللہ علیہ وسلم ۄن ز اتھ نفر چھ اللہ کہ عظیم ناوس سۭتۍ دعا بناومت۔", "اتھ ناوس سۭتۍ بناونہٕ آمتس دواہک جواب چھ یوان دنہٕ۔"),
        "dua_ism_azam_ahad_samad" to DuaText("اسلام اعظم: الأحد اسماد", "اے اللہ، بہٕ چھس تۄہہ پوچھنان، بہٕ چھس گواہن دوان ز تہۍ چھو اللہ۔ تہنٛدس علاوٕ چھ نہٕ کانٛہہ تہ دیوتا، اکھ، خود کفیل، یس نہ چھ پیدٕ گژھان تہٕ نہ چھ گژھان، تہٕ نہ چھ أمس سۭتۍ کانٛہہ تہ موازنہٕ۔", "پیغمبر صلی اللہ علیہ وسلم ۄن ز اتھ نفرٕ کوٚر اللہ سٗند ساروی کھوتہٕ بوٚڑ ناو پوچھن۔", "ییٚلہ امہ سۭتۍ پوچھنہٕ چھ یوان، سہ چھ دوان ؛ ییٚلہ امہ سۭتۍ بلاونہٕ چھ یوان، سہ چھ جواب دوان۔"),
        "dua_thabbitni_hadiyan" to DuaText("مےٚ بناو مضبوط، رہنما تہٕ رہنما۔", "اے اللہ، مےٚ بناو مضبوٗط، تہٕ مےٚ بناو سہ یس ہدایت تہٕ ہدایت چھ دوان۔", "پیغمبر صلی اللہ علیہ وسلم ین بنٲو یہ دعا جاریرس (ر) خٲطرٕ (پنٛنس خٲطرٕ'تھبٹنی')۔", "جاریر (آر اے) خٲطرٕ چھ اصلی دوا لفظ'تھبٹ-ہو'استعمال کران۔"),
        "dua_rabbighfir_tub_alayya" to DuaText("معاف کر تہٕ قبول کر میٚون پچھتاوا۔", "اے میرے رب، معاف کر تہٕ قبول کر میٚون تاوان۔ بے شک، تو چھ تاوانک مٲلک، رحم کرن وول۔", "اکہ نشستس منٛز ہتہٕ بٔد-پیغمبر اسلام صلی اللہ علیہ وسلم سند عمل۔", "سٲتھی ین کوٚر أکس نشستس منٛز ساسہٕ بٔٹھۍ یہ ونن والؠن پیغمبر صلی اللہ علیہ وسلم سنٛد شمار۔"),
        "dua_rafiq_ala" to DuaText("مرون وٲلہ شخصٕ سند دعا", "اے اللہ، معاف کر مےٚ، رحم کر مےٚ تہٕ سٲتھیس سۭتۍ۔", "پیغمبر اسلام صلی اللہ علیہ وسلم سند آخری دعا-بیمار نفرٕ خٲطرٕ ز سہ ییہٕ پننس پانس خٲطرٕ ون۔", "پیغمبر صلی اللہ علیہ وسلم ہن کٔر پنٛنہ مرنہٕ وز یہ دعا۔"),
        "dua_la_bas_tahur" to DuaText("بیمارن آرام دٲری: صفائی", "کانٛہہ تہ نقصان چھنہٕ ؛ اگر اللہ چاہے یہ چھ اکھ پاکیزگی (گناہن نش)۔", "ییٚلہ بیمار گژھن چھ سہ کر سہس۔", "یہ ووٚنۍ پیغمبر اسلام صلی اللہ علیہ وسلم ین بیمارؠن نش ملاقاتہٕ دوران۔"),
        "dua_talqeen" to DuaText("مرٕنہ خٲطرٕہ تلقیں", "کٲنہہ تہ چھ نہٕ عبادت کرنک حق سوائے اللہ کہ۔", "مران نفرس نزدیٖک کر کالیمہ ہنٛز تلاوت (تمن یہ وننہٕ خٲطرٕ کر نہٕ مجبور)۔", "یس تہ سنٛد آخری لفظ چھ'لا الہ اللہ'تم گژھن جنتس منٛز دٲخل (ابو داؤد 3116)۔"),
        "dua_ahyini_ma_kanat" to DuaText("مرنہٕ کہ بجائے چھ مران۔", "اے اللہ، مےٚ تھٲیو تتھ وقتس تام زندٕ یوٚتام زندگی میانہ خٲطرٕ بہتر آسہ، تہٕ مےٚ تھٲیو تمہٕ وقتہٕ ییٚلہ موت میانہ خٲطرٕ بہتر آسہ۔", "مشکلس منٛز موتچ خواہش کرنہٕ بجایہٕ۔", "پیغمبر اسلام صلی اللہ علیہ وسلم ین دیت موتچ خواہش رکاونہٕ تہٕ امہ بجایہ ہیچھناو یہ۔"),
        "dua_for_one_i_cursed" to DuaText("کٲنٛسہ خٲطرٕ چھ مےٚ الفاظ سۭتۍ تکلیف۔", "اے اللہ، کانٛہہ تہ ایمان یتھ مےٚ بے عزتی چھ کٔرمٕژ، یہ چھ قیامت کس دۄہ أمس خٲطرٕ تۄہہ نزدیک گژھنک ذریعہٕ بناوان۔", "تہنٛدس نفرس خٲطرٕ یس سۭتۍ تو٘ہہ غصےس منٛز بدتمیز کتھ کران چھو۔", "پیغمبر اسلام صلی اللہ علیہ وسلم سند اکھ دعا۔"),
    )
}
